class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n = s_cnt = e = w = 0
        ans = 0

        for i, c in enumerate(s):
            if c == 'N':
                n += 1
            elif c == 'S':
                s_cnt += 1
            elif c == 'E':
                e += 1
            else:
                w += 1

            length = i + 1
            distance = abs(n - s_cnt) + abs(e - w)
            ans = max(ans, min(length, distance + 2 * k))

        return ans
